  await type("The newer native words I am still editing"); held.release(); await flush(); await new Promise(resolve => setTimeout(resolve, 320)); await flush();
  expect(editor().props.value).toBe("The newer native words I am still editing"); expect((await loadJournalDraft(KEY, await journalDraftScope(USER)))!.draft.text).toBe("The newer native words I am still editing");
  const receipt = [...stored.values()][0]!; expect(decryptEntry({ dataKey: KEY }, USER, receipt.client_entry_id, receipt.blob, 1).text).toBe(ORIGINAL);
