  expect(await storage.getItem(scope.slot)).toBe(replacement); expect((await loadJournalDraft(next, scope))!.draft.text).toBe("replacement native words"); expect(vault.get().dataKey).toEqual(next); expect(vi.mocked(Alert.alert).mock.calls).toEqual([]);
